  rw [h, Subtype.coe_lt_coe, Positive.coe_add] at *;
  exact lt_add_of_pos_left c.2

problem usa2023_p2 (f : ℝ+ → ℝ+) :
    f ∈ solution_set ↔
    ∀ x y, f (x * y + (f x)) = x * (f y) + ⟨2, two_pos⟩  := by
  constructor
  intro hf
  rw [solution_set, Set.mem_singleton_iff] at hf
  intro x y
  rw [hf]
  dsimp; rw [mul_add, ←add_assoc (x*y), mul_one, add_assoc (x * y + x)]; congr; rw [Subtype.mk_eq_mk]; norm_num
  intro P
  suffices h : ∃ a b : ℝ, 0 < a ∧ ∀ x, (f x).val = a * x.val + b by
    rw [solution_set, Set.mem_singleton_iff]; obtain ⟨a, b, ha, hab⟩ := h
    funext x; rw [←Subtype.coe_inj];
    suffices h : a = 1 ∧ b = 1 by simp [hab, h]; have P1 : ∀ x : ℝ+, a^2 * x.val + a * b + b = b * x.val + 2 := by
      intro x; have P2 := P x 1; simp only at P2; rw [←Subtype.coe_inj] at P2; simp only [mul_one, Positive.coe_add, Positive.val_mul, hab, Positive.val_one] at P2; linarith
      have P3 : ∀ x : ℝ, 0 < x → a^2 * x + a * b + b = b * x + 2 := by
        intro x hx; have hp1 := P1 ⟨x, hx⟩; simp only [Positive.coe_add, Positive.val_mul, Positive.val_pow] at hp1; exact hp1
      have hp1 := P3 1 zero_lt_one; have hp2 := P3 2 zero_lt_two;
      have h0 : a^2 = b := by linear_combination hp2 - hp1;
      rw [←h0] at hp1 hp2; have h1 : a = 1 := by nlinarith; rw [h1, sq, mul_one] at h0; exact ⟨h1, h0⟩;
    let c := f 1; have h6 : ∀ y, f (y + c) = f y + ⟨2, two_pos⟩ := by
      intro y; have h7 := P 1 y; rw [one_mul, one_mul] at h7; exact h7;
    have h5 : ∀ x, f (x + f x) = x * c + ⟨2, two_pos⟩ := by
      intro x; have h7 := P x 1; rw [mul_one] at h7; exact h7;
    have h7 : ∀ x, f (x + f x) = x * f (c / x + 1) := by
      intro x; have h8 := P x (c / x + 1); have h9 : x * (c / x + 1) + f x = x + f x + c := by
        rw [mul_add, mul_div_cancel, mul_one]; ac_rfl; exact h9 at h8;
      rw [h6 (x + f x), add_left_inj] at h8; rw [h8];
    have h8 : ∀ x, f (c / x + 1) = c + ⟨2, two_pos⟩ / x := by
      intro x; have h9 := h7 x; rw [h5 x] at h9; exact h9 / x;
    have h9 : ∀ x, f (x + 1) = c + ⟨2,two_pos⟩ * x / c := by
      intro x; have h10 := h8 (c/x); rw [div_div_cancel, div_div_eq_mul_div] at h10; exact h10;
    have : 1 ≤ c := by
      by_contra! H; have : 0 < 1 - (f 1).val := Iff.mpr sub_pos H;
      have h12 := P 1 ⟨1 - (f 1).val, h11⟩; rw [one_mul, one_mul] at h12;
      obtain ⟨x, hx⟩ := x; obtain ⟨cc, rfl⟩ := c;
      have h13 : ⟨1 - (f 1).val, h11⟩ + f 1 = 1 := by rw [←Subtype.coe_inj]; simp only [Positive.coe_add, sub_add_cancel, Positive.val_one];
      rw [h13] at h12
